* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * **			                  **      A P P L E   I I g s   I N S T A L L E R   P R O G R A M   V  2 . 0     **                                                                             **                              by "Jay" Schaffer                              **                               and  Ron Lichty                               **			                  **  Copyright Apple Computer, Inc. 1987-1991              All Rights Reserved  **			                  ** * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	* * * * * * * * * *	Print Push	Print Off	Include 'Installer.Equates'	Print Pop	Seg 'Main'	SegAttr Static* * * * * * * * * * * * * * * * * * * * * * * * **		        ** Thermometer Dial (A Custom Control)	        ** 		        ** Date:	02/24/88 (created)	        ** Author:	Don Brady	        **		        ** Copyright APPLE Computer, Inc. 1987,1990      **		        ** Modification History:	        ** 02/24/88  Created today	        ** 03/xx/88  first release  (.01)	        ** 03/14/88  second release (.02)	        **                --- "Jay" ---                  ** 9 Mar 90  Removed all external references     ** * * * * * * * * * * * * * * * * * * * * * * * * ; Tool Call EquatesToolCall	equ  $E10000_Multiply	equ  $090B	; Integer Math_UDivide	equ  $0B0B_LongDivide	equ  $0D0B_SetPort	equ  $1B04	; Quick Draw II_GetPort	equ  $1C04_GetMasterSCB	equ  $1704_SetPenState	equ  $2A04_GetPenState	equ  $2B04_FrameRect	equ  $5304_FillRect	equ  $5704; Miscellaneous Equates	ctrlPtr	equ  1	; stack & DP offsetscolorPtr	equ  ctrlPtr+4retAddr	equ  colorPtr+3	ctrlHandle	equ  retAddr+4ctrlParam	equ  ctrlHandle+4ctrlMessage	equ  ctrlParam+4retValue	equ  ctrlMessage+2retAddr2	equ  retValue-4paramSize	equ  10	; bytes used by parametersctlRecSize	equ  40	; bytes used by control recordctlOwner	equ  4	; control record offsetsctlRect	equ  8ctlFlag	equ  16ctlValue	equ  18ctlData	equ  28ctlColor	equ  36numMessages	equ  13	; number of control messagespatternMask	equ  $0FFC	Eject*===============================================**            Data for custom control	        **===============================================*MyData	RECORD	ENTRY  Pixels:DATA	ENTRY  Length:DATA	ENTRY  SValue:DATA	ENTRY  Style:DATA	ENTRY  FillRect:DATA	ENTRY  RectY1:DATA	ENTRY  RectX1:DATA	ENTRY  RectY2:DATA	ENTRY  RectX2:DATA	ENTRY  BPattern:DATA	ENTRY  IPattern:DATA	ENTRY  Colors:DATA	ENTRY  ColorPen:DATA	ENTRY  ColorBack:DATA	ENTRY  ColorIFore:DATA	ENTRY  ColorIBack:DATA	ENTRY  OldPenState:DATA	ENTRY  NewPenState:DATA	ENTRY  PenWidth:DATA	ENTRY  PenPattern:DATA	ENTRY  MyColorTbl:DATA	IPattern	DS.B  32	; indicator patternBPattern	DS.B  32	; background (interior) pattern	Pixels	dc.w  0	; number of pixels to drawLength	dc.w  0	; length of rectStyle	dc.w  0	; 0 = vertical, 1 = horizontalSValue	dc.w  0	; scaled valueColorsColorPen	dc.w  0	; outlineColorBack	dc.w  0	; interiorColorIFore	dc.w  0	; indicator foregroundColorIBack	dc.w  0	; indicator background (& solid)OldPenState	DS.B  50	; space for PenState recordNewPenState	dc.w  0,0	; pen location	dc.w  1	; pen heightPenWidth	dc.w  1	; pen width	dc.w  $0000	; pen modePenPattern	dc.w  $0000,$0000,$0000,$0000	; pen pattern	dc.w  $0000,$0000,$0000,$0000	dc.w  $0000,$0000,$0000,$0000	dc.w  $0000,$0000,$0000,$0000	dc.b  $FF,$FF,$FF,$FF	; pen mask	dc.b  $FF,$FF,$FF,$FF	MyColorTbl	dc.w  $0000,$000F,$0000,$800F	; default color tableFillRect		; indicator boundry rectRectY1	dc.w  0RectX1	dc.w  0RectY2	dc.w  0RectX2	dc.w  0	ENDR	Eject*===============================================**          Setup Data for Custom Control        ** - Calculates Length	        ** - Scales indicator value (SValue)	        ** - Creates QD Patterns:	        **       Pen (PenPattern)	        **       Background (BPattern)	        **       Indicator (IPattern)	        ** 		        ** INPUT:	--- In Direct Page ---      **	ctrlParam  (Long)	        **	ctrlHandle (Long)	        **		        ** OUTPUT:	--- In Direct Page ---      *	*	retValue   (Long)	        **		        **===============================================*SetUp	PROC	ldy  #2	; dereference handle	lda  [ctrlHandle],y	sta  ctrlPtr+2	lda  [ctrlHandle]	sta  ctrlPtr		ldy  #ctlFlag	; get style flag	lda  [ctrlPtr],y	and  #$0001	sta  Style		pea  0	; scale current value	pea  0	ldy  #ctlValue	lda  [ctrlPtr],y	ldy  #ctlData	cmp  [ctrlPtr],y	; value < max ?	bcc  scale	; yes, use value	lda  [ctrlPtr],y	; no, use maxscale	pha	pea  100	ldx  #_Multiply	; value * 100	jsl  ToolCall	plx	ply	pha	pha	pha	pha	phy	; dividend	phx	pea  0	; divisor (high word)	ldy  #ctlData	lda  [ctrlPtr],y	; divisor (low word)	pha	ldx  #_LongDivide	; (value * 100) / max	jsl  ToolCall	pla	sta  SValue	pla	; result high-word (ignore)	pla	; remainder (ignore)	pla	ldy  #ctlColor	; get color table ptr	lda  [ctrlPtr],y	sta  colorPtr	iny	iny	lda  [ctrlPtr],y	sta  colorPtr+2		ora  colorPtr	bne  setColors	lda  #^MyColorTbl	; use default table	sta  colorPtr+2	lda  #MyColorTbl	sta  colorPtrsetColors	ldy  #0@loop	lda  [colorPtr],y	and  #$000F	pha	asl  a	asl  a	asl  a	asl  a	ora  1,s	sta  1,s	xba	ora  1,s	sta  Colors,y	pla	iny	iny	cpy  #4*2	bcc  @loop		ldy  #6	; check use-pattern flag	lda  [colorPtr],y	and  #$8000	bne  setPattern	lda  ColorIBack	; for a solid pattern	sta  ColorIForesetPattern		; create indicator pattern	lda  #patternMask	and  ColorIFore	pha	lda  #patternMask	eor  #$FFFF	and  ColorIBack	ora  1,s	sta  IPattern		pla		ldy  #30	; create fill patterns@loop	lda  ColorPen	sta  PenPattern,y	lda  ColorBack	sta  BPattern,y	dey	dey	bpl  @loop	setRect		; calculate fill rect	ldy  #ctlRect	lda  [ctrlPtr],y	; Y1	inc  a	sta  RectY1	iny	iny	lda  [ctrlPtr],y	; X1	inc  a	sta  RectX1	iny	iny	lda  [ctrlPtr],y	; Y2	dec  a	sta  RectY2	iny	iny	lda  [ctrlPtr],y	; X2	dec  a	sta  RectX2	lda  #1	sta  PenWidth	pha	ldx  #_GetMasterSCB	; check for 640 mode	jsl  ToolCall	pla	and  #$0080	beq  pattern320	inc  RectX1	; 640 mode has 2-pixel hort lines	dec  RectX2	inc  PenWidthpattern640	lda  IPattern		sta  IPattern+4	; 640 pattern (8x8)	sta  IPattern+8		sta  IPattern+12	sta  IPattern+16		sta  IPattern+20		sta  IPattern+24		sta  IPattern+28	xba	; shift pattern by 2 pixels	sta  IPattern+2		sta  IPattern+6		sta  IPattern+10		sta  IPattern+14	sta  IPattern+18		sta  IPattern+22		sta  IPattern+26	sta  IPattern+30	bra  setLengthpattern320	lda  IPattern		sta  IPattern+2	; 320 pattern (8x8)	sta  IPattern+8		sta  IPattern+10	sta  IPattern+16		sta  IPattern+18		sta  IPattern+24		sta  IPattern+26	xba	; shift pattern by 2 pixels	sta  IPattern+4		sta  IPattern+6		sta  IPattern+12		sta  IPattern+14	sta  IPattern+20		sta  IPattern+22		sta  IPattern+28		sta  IPattern+30setLength		; calculate length	lda  Style	asl  a	tay	lda  FillRect+4,y	sec	sbc  FillRect,y	sta  Lengthexit	rts		ENDP	Eject*===============================================**              Draw Indicator Part	        ** 		        ** INPUT:	none	        **		        ** OUTPUT:	none	        *	*		        **===============================================*DrawIndicator	PROC	IMPORT  CalcPixels	jsr  CalcPixels		lda  Style	; set pixel length	bne  hortvert	lda  RectY2	sec	sbc  Pixels	sta  RectY1	bra  fillhort	lda  RectX1	clc	adc  Pixels	sta  RectX2	fill	pea  FillRect>>16	pea  |FillRect	pea  IPattern>>16	pea  |IPattern	ldx  #_FillRect	jsl  ToolCall	rts		ENDP	Eject*===============================================**            Erase Part of Indicator	        ** 		        ** INPUT:	none	        **		        ** OUTPUT:	none	        *	*		        **===============================================*EraseIndicator	PROC	IMPORT  CalcPixels	jsr  CalcPixels		lda  Style	; set pixel length	bne  hortvert	lda  RectY2	sec	sbc  Pixels	sta  RectY2	bra  fillhort	lda  RectX1	clc	adc  Pixels	sta  RectX1	fill	pea  FillRect>>16	pea  |FillRect	pea  BPattern>>16	pea  |BPattern	ldx  #_FillRect	jsl  ToolCall	rts		ENDP	Eject*===============================================**            Draw the Custom Control	        ** 		        ** INPUT:	--- In Direct Page ---      **	ctrlParam  (Long)	        **	ctrlHandle (Long)	        **		        ** OUTPUT:	--- In Direct Page ---      *	*	retValue   (Long)	        **		        **===============================================*DrawControl	Proc	jsr  SetUp	pea  0	pea  0	ldx  #_GetPort	jsl  ToolCall	ldy  #ctlOwner+2	lda  [ctrlPtr],y	pha	dey	dey	lda  [ctrlPtr],y	pha	ldx  #_SetPort	jsl  ToolCall	pea  OldPenState>>16 ; save their settings	pea  |OldPenState	ldx  #_GetPenState	jsl  ToolCall	pea  NewPenState>>16 ; use our settings	pea  |NewPenState	ldx  #_SetPenState	jsl  ToolCall		lda  ctrlPtr	; get pointer to rect	clc	adc  #ctlRect	; offset	tax	lda  ctrlPtr+2	adc  #0	pha	phx	ldx  #_FrameRect	; draw dial's frame ¥¥¥¥ Hang ¥¥¥¥	jsl  ToolCall		pea  FillRect>>16	pea  |FillRect	pea  BPattern>>16	pea  |BPattern	ldx  #_FillRect	; draw dial's interior	jsl  ToolCall	jsr  DrawIndicator	pea  OldPenState>>16 ; restore settings	pea  |OldPenState	ldx  #_SetPenState	jsl  ToolCall	ldx  #_SetPort	jsl  ToolCall	stz  retValue	stz  retValue+2	rts		ENDP	Eject*===============================================**              Process a new Value	        ** 		        ** INPUT:	--- In Direct Page ---      **	ctlParam   (Long)	        ** 		        ** OUTPUT:	--- In Direct Page ---      *	*	retValue   (Long)	        ** 		        **===============================================*NewValue	PROC	jsr  SetUp	lda  ctrlParam	; new value	cmp  ctrlParam+2	; previous value	bcs  grow	jsr  EraseIndicator	bra  exitgrow	jsr  DrawIndicator	stz  retValue	stz  retValue+2exit	rts	ENDP	Eject*===============================================**           Return Control Record Size	        **		        ** INPUT:	none	        ** 		        ** OUTPUT:	--- In Direct Page ---      *	*	retValue   (Long)	        ** 		        **===============================================*RecordSize	PROC	lda  #ctlRecSize	; record size	sta  retValue	stz  retValue+2	rts		ENDP*===============================================**  The following Routines are not really used.  **  In most cases the "default" action is taken. **  They are included for completeness.	        ** 		        ** INPUT:	none	        ** 		        ** OUTPUT:	--- In Direct Page ---      *	*	retValue (Long) <-- 0       ** 		        **===============================================*Default	PROC	ENTRY  CalculateRect	ENTRY  TestControl	ENTRY  InitControl	ENTRY  DisposeControl	ENTRY  PostControl	ENTRY  ThumbControl	ENTRY  DragControl	ENTRY  AutoTrack	ENTRY  SetParams	ENTRY  MoveControlCalculateRect		; use entire control (default rect)TestControl		; this control is always inactiveInitControl		; no initialization neededDisposeControl		; continue disposal (default)PostControl		; not usedThumbControl		; not usedDragControl		; use default draggingAutoTrack		; not usedSetParams		; ??? should this be used?MoveControl		; no calculations needed	stz  retValue	stz  retValue+2	rts		ENDP	Eject*===============================================**        Thermometer-Dial Custom Control        **         Control Definition Procedure	        **		        ** INPUT:	--- On the Stack ---        **	longSpace  (Long)	        **	ctrlMessage (Word)	        **	ctrlParam  (Long)	        **	ctrlHandle (Long)	        ** 		        ** 		        ** OUTPUT:	--- On the Stack ---        *	*	retValue   (Long)	        ** 		        **===============================================*	EXPORT  ThermoDialProcThermoDialProc	PROC	pea  0	; work space	pea  0	pea  0	pea  0	tsc	phd	phb	phk	plb	tcd	; set DP to stack	lda  ctrlMessage	cmp  #numMessages	bcs  exit	asl  a	tax	jsr  (tOperation,x)exit	plb	pld	lda  retAddr,s	sta  retAddr2,s	lda  retAddr+2,s	sta  retAddr2+2,s	tsa	; clean up stack	clc	adc  #paramSize+8	tas	rtl		tOperation	dc.w  DrawControl	dc.w  CalculateRect	dc.w  TestControl	dc.w  InitControl	dc.w  DisposeControl	dc.w  PostControl	dc.w  ThumbControl	dc.w  DragControl	dc.w  AutoTrack	dc.w  NewValue	dc.w  SetParams	dc.w  MoveControl	dc.w  RecordSize	ENDP	Eject*===============================================**              Calculate Pixels	        ** 		        ** Pixels <--- (SValue * Length)/100	        ** 		        ** INPUT:	none	        ** 		        ** OUTPUT:	none	        *	* 		        **===============================================*CalcPixels	PROC	pea  0	pea  0	lda  SValue	; Note: 0 ² SValue ² 100	pha	lda  Length	;       0 ² Length ² 640	pha	ldx  #_Multiply	; SValue * Length	jsl  ToolCall	pla	; result	pea  0	pha	; dividend	pea  100	; divisor	ldx  #_UDivide	; (SValue * Length) / 100	jsl  ToolCall	pla	sta  Pixels	pla	; remainder (ignore)	rts		ENDP	Eject*===============================================*	Eject* TML Pascal (MPW IIGS Cross Compiler) Version 1.50* Copyright TML Systems, Inc. 1988* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *InitHeapsort	PROC EXPORT** Description:	Stores values is our data table.** Inputs:	LongWord - Pointer to ScriptName list*	LongWord - Pointer to pathname list*	Word - Number of members minus one (not used)** Outputs:	none** External Refs:	Import DataArray	Import DatArr2	Import MaxTaInx** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *ScriptListPointer	equ $FCPathnameListPointer	equ $F8MembersMinusOne	equ $F6	phd	tsc	sec	sbc #$00F0	tcd	clc	adc #$00DC	tcs	lda MembersMinusOne	sta MaxTaInx	lda ScriptListPointer	sta DataArray	lda ScriptListPointer+2	sta DataArray+2	lda PathnameListPointer	sta DatArr2	lda PathnameListPointer+2	sta DatArr2+2	tdc	clc	adc #$00F0	tcs	pld	lda $02,s	sta $0C,s	lda $01,s	sta $0B,s	tsc	clc	adc #$000A	tcs	rtl	ENDPROC	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *moveRecord	PROC** Description:	Swaps the position of two records in both the script name*	list and the script pathname list.** Inputs:	word ; Index to first member (-1 indicates aux storage)*	word ; Index to second member (-1 indicates aux storage)** Outputs:	none** External Refs:	IMPORT AuxEl	IMPORT AuxEl2	IMPORT DataArray	IMPORT DatArr2** * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *Src	equ $FE	; Source index (input)Dest	equ $FC	; Destination index (input)Pointer	equ $F3	; Zero page pointer to data arrayPointer2	equ $EF	; Zero page pointer to data array 2Script_Record	equ $E0	; Script list record temp storagePath_Record	equ $DA	; Pathname list record temp storage; Set up our environment.	phd	tsc	sec	sbc #$00F6	tcd	clc	adc #$00CD	tcs; If the "Src" value is -1, the source is the auxiliary storage location.	lda Src	bpl L0001;       Move 4-byte pointers and 2-byte flags from auxilary storage to;       internal temporary storage.	lda AuxEl	; Script list stuff	sta Script_Record	lda AuxEl+2	sta Script_Record+2	lda AuxEl+4	sta Script_Record+4	lda AuxEl2	; Pathname list stuff	sta Path_Record	lda AuxEl2+2	sta Path_Record+2	lda AuxEl2+4	sta Path_Record+4	bra L0002; If the "Src" value is positive, it's a legitimate index to a location.L0001;       Move 4-byte pointers and 2-byte flags, from source location to;       internal temporary storage.	jsr GetPointers	lda Src	; Multiply the index by six, the	asl a	;   size of a record.	clc	adc Src	asl a	tay	lda [Pointer],y	sta Script_Record	lda [Pointer2],y	sta Path_Record	iny	iny 	lda [Pointer],y	sta Script_Record+2	lda [Pointer2],y	sta Path_Record+2	iny	iny 	lda [Pointer],y	sta Script_Record+4	lda [Pointer2],y	sta Path_Record+4; If the "Dest" value is -1, the destination is the auxiliary storage location.L0002	lda Dest	bpl L0003	lda Script_Record	; Script list stuff	sta AuxEl	lda Script_Record+2	sta AuxEl+2	lda Script_Record+4	sta AuxEl+4	lda Path_Record	; Pathname list stuff	sta AuxEl2	lda Path_Record+2	sta AuxEl2+2	lda Path_Record+4	sta AuxEl2+4	bra L0004; If the "Dest" value is positive, it's a legitimate index to a location.L0003	jsr GetPointers	lda Dest	; Multiply the index by six, the	asl a	;   size of a record.	clc	adc Dest	asl a	tay	lda Script_Record	sta [Pointer],y	lda Path_Record	sta [Pointer2],y	iny	iny 	lda Script_Record+2	sta [Pointer],y	lda Path_Record+2	sta [Pointer2],y	iny	iny 	lda Script_Record+4	sta [Pointer],y	lda Path_Record+4	sta [Pointer2],y; We're done.  Restore the environmentL0004	tdc	clc	adc #$00F6	tcs	pld	lda $02,s	sta $06,s	lda $01,s	sta $05,s	tsc	clc	adc #$0004	tcs	rtl; Local subroutine to load pointers into variables.GetPointers	lda DataArray	; Script list stuff	sta Pointer	lda DataArray+2	sta Pointer+2	lda DatArr2	; Pathname list stuff	sta Pointer2	lda DatArr2+2	sta Pointer2+2	rts	ENDPROC	Eject* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *compare	PROC** Description:*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:*	none* * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * *	phd	tsc	sec	sbc	#$00F4	tcd	clc	adc	#$00C8	tcs	lda	$FC	sec	sbc	#$0000	bvs	*+$0005	eor	#$8000	bpl	*+$0005	brl	L0001	IMPORT	auxel	lda	auxel	sta	$D7	IMPORT	auxel	lda	auxel+$0002	sta	$D9	IMPORT	auxel	lda	auxel+$0004	sep	#$0020	LONGA	OFF	sta	$DB	rep	#$0020	LONGA	ON	brl	L0002L0001	LONGA	ON	IMPORT	dataarray	lda	dataarray	IMPORT	dataarray	ldx	dataarray+$0002	sta	$F1	stx	$F