ameStoreLoop	iny	tyx	ldy SrcY	; (Can't just "inc SrcY" because	iny	;  LongA is off!)	sty SrcY	lda [<ZPTemp1],y	cmp #Return	beq ScriptNameStoreDone	txy	sta [<ZPTemp],y	bra ScriptNameStoreLoopScriptNameStoreDone	LongA On	rep #$0020	txy	ldx #ScriptFlagField	lda Read_Buffer,x	; Get the flags word	pha	; Save the flags	and #$00FF	; Look at 2nd character	cmp #'X'	; Is directory selection required?	bne @NoDirectory	lda #bDirReq	bra @StoreIt@NoDirectory	lda #%0000000000000000@StoreIt	sta [<ZPTemp],y	pla	; Restore the flags	and #$DF00	; Look at 1st character (upper case)	cmp #'R'*$100	; Is REMOVE command valid?	beq @NoRemove	lda [<ZPTemp],y	ora #bNoRemove	; else prevent REMOVE button	sta [<ZPTemp],y@NoRemove	ldx #ScriptFlagPrvtBoot	lda Read_Buffer,x	; Get the word	and #$00FF	; Look at PreventBoot flag	cmp #'B'	; prevent installation of script to Boot disk?	bne @BootOK	lda [<ZPTemp],y	ora #bPreventBoot	sta [<ZPTemp],y@BootOK	jsr ReBuildPointers	; Rebuild the pointers	lda ScriptListHdl+2	; Lock the list back down...	pha	lda ScriptListHdl	pha	ldx #Hlock	jsl ToolLocator	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; Now take care of the ScriptFile list;       Determine the current size of the memory segment holding the;       ScriptFileList and add on the additional size needed for the;       new entry. Then resize the memory and get a pointer to it.	pha	; Get the current size	pha	lda ScriptFileHdl+2	pha	lda ScriptFileHdl	pha	ldx #GetHandleSize	jsl ToolLocator	pla	plx	bcc @Continue	brl AddToDone@Continue	clc	; Add on additional needed	sta ScriptIndex	ldy #0002	adc [<PathBuf],y	; (Pathname length)	adc #0009	; (List entry size + length word	tay	;      + trailing null)	txa	sta ScriptIndex+2	adc #0000	sty NewSize	sta NewSize+2	lda ScriptFileHdl+2	; Save the old pointer for later use	pha	;   when the pointer table is rebuilt	lda ScriptFileHdl	pha	jsl Dereference	pla	sta Ori