ect page.  (Does not use X or Y).;; Side Effects:	SEE SPECIAL NOTES.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	longA Off	jsl UpperCase8bit	sta <OurChar	xba	; get second char into A	jsl UpperCase8bit	cmp <OurChar	rtl	longA On	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .Alphabetize	; (External entry point);; Description:	Script List:;	Locks down the lists, alphabetizes them, resets the list;	size in ctlData (causing a redraw) and returns pointer and;	size information.;; Inputs:	none;; Outputs:	X & Y contains the script list pointer;	A contains the script list size;; Uses:	ScriptFileHdl - Handle to script pathname list;	ScriptFileHdl - Handle to script pathname list;	ScriptListHdl - Handle to ScriptName list;	ScriptListSize - number of members;; Side Effects:	Makes a _NewList2 call to change the list size value which;	causes the list to be redrawn.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	phb	; Called by StartUp segment	phk	plb	lda ScriptListHdl+2	; Lock the list down...	pha	lda ScriptListHdl	pha	ldx #Hlock	jsl ToolLocator	lda ScriptFileHdl+2	; Lock the list down...	pha	lda ScriptFileHdl	pha	ldx #Hlock	jsl ToolLocator	jsl GetListPointers; Alphabetize the list of ScriptName pointers and shuffle the list of; ScriptFilename records to match.	pei <ScriptListPtr+2 ; Pointer to list of ScriptName pointers	pei <ScriptListPtr	pei <ScriptFilePtr+2 ; Pointer to list of pathname pointers	pei <ScriptFilePtr	lda ScriptListSize	dec a	pha	; Maximum index (list size - 1)	jsl InitHeapsort	pea 0000	; Lo-index = zero	lda ScriptListSize	dec a	pha	; Hi-index = list size - 1	jsl Sort; If the window setup is complete, we're adding scripts from a disk that was; just now inserted.  Resize the list control.	bit WindowSetupComplete	bpl AlphabetizeExit	bit DialogFlag	; Don't do anything if Easy Update	bmi AlphabetizeExit	;   is currently running.	pea 0000	;drawPtr     (member drawing routine)	pea 0000	pea $FFFF	; listStart   (item number)	lda <ScriptListPtr+2 ;listRef     (handle)	pha	lda <ScriptListPtr	pha	pea 0000	; listRefDesc (listRef is a pointer)	lda ScriptListSize	; listSize	pha	lda ScriptListCtlHdl+2 ; ctlHandle	pha	lda ScriptListCtlHdl	pha	ldx #NewList2	jsl ToolLocator; Set up return values and exit.AlphabetizeExit	ldx <ScriptListPtr	ldy <ScriptListPtr+2	lda ScriptListSize	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .AddColon	; (Local subroutine);; Description:	Adds a trailing colon to a string (volume name) so that;	we can concatenate filenames to it.;; Inputs:	none;; Outputs:	none;; Uses:	<PathBuf - Location of string (volume name);	PathLength - String length after colon is added; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pea ColonBuf>>16	; Concatenate a colon to the directory	pea |ColonBuf	;   name.  (The buffer always has a	pei <PathBuf+2	;   trailing null, so this concatenation	pei <PathBuf	;   will always fit.)	pei <PathBuf+2	pei <PathBuf	jsl GStrConcat	ldy #0002	lda [<PathBuf],y	;   and the pathname's new length word	sta PathLength	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CheckEntry	; (Local subroutine);; Description:	Checks the current directory entry in Get_Dir_Entry;	parameter table and then opens the file and reads in;	its header to see if it is a legitimate script file;	that is compatible with the current Installer.;;	NOTE:  This routine appends the script filename onto;	       <PathBuf (the directory's full pathname).  Be;	       sure to restore the directory's length byte;	       before calling this routine again!;; Inputs:	none;; Outputs:	c-flag clear: no errors;	c-flag set: error occurred or file is incompatible or not;	            a script file.  A-reg contains error code, if;	            any.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .; First check the filetype and auxtype.	lda File_Type	; Is it a script file?	ldx Aux_Type	cmp #OldScriptType	; Is it an old TXT file?	beq FoundOne	cmp #NewScriptType	bne @0	cpx #ScriptAux	beq FoundOne@0	brl NotAScript; We must OPEN the file and check its header to see if it is really a script file.FoundOne	pea NameBuffer>>16	; Concatenate filename to directory name	pea |NameBuffer	pei <PathBuf+2	pei <PathBuf	pei <PathBuf+2	pei <PathBuf	jsl GStrConcat	bcs @0	ldx <PathBuf	ldy <PathBuf+2	bra OpenTheFile@0	pha	pha	pei <PathBuf+2	pei <PathBuf	jsl GStrResize	plx	stx <PathBuf	ply	sty <PathBuf+2	bcc OpenTheFile	lda PathLength	; Oops, the concatenation failed the	ldy #0002	;   first time.  Restore the original	sta [<PathBuf],y	;   length word and try again.	bra FoundOne;       Open the file and read in the header.OpenTheFile	inx	; Adjust buffer ptr to point to	bne @00	;   class 1 input string.	iny@00	inx	bne @000	iny@000	stx <ZPTemp	; Store the pathname pointer	sty <ZPTemp+2	jsr ReadScriptHeader	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .ReadScriptHeader	; (Local subroutine);;	Reads the header of a suspected script file and checks it;	to verify that it is truely a script and compatible with;	this version of the Installer.;; Inputs:	X & Y contain pointer to the full pathname;; Outputs:	cFlag clear if it is a compatible script.;	cFlag set if it is incompatible or not a script.;	Sets oScriptNameField to offset of ScriptNameField.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . 	stx Open_Path	sty Open_Path+2	jsl GSOS	; Open the script file	dc.w Open	dc.l OpenParms	bcs NotAScript	lda Open_Ref_Num	; Distribute the reference number	sta Read_Ref_Num	sta Close_Ref_Num	jsl GSOS	dc.w Read	dc.l ReadParms	pha	; Save the error code	jsl GSOS	dc.w Close	dc.l CloseParms	pla	bne NotAScript;       Check to see if it is REALLY a script file	lda Read_Buffer	; Does it begin:	cmp #'CS'	;  'SCRIPT<return><return>' ?	bne NotAScript	lda Read_Buffer+2	cmp #'IR'	bne NotAScript	lda Read_Buffer+4	cmp #'TP'	bne NotAScript	lda Read_Buffer+6	cmp #$0D0D	bne NotAScript; We've found a script file.  Will it run with this version of the Installer?FoundScript	ldy #ScriptVerField	lda Read_Buffer,y	iny	iny	ldx Read_Buffer,y	cmp cVersion	; 1.00 ?	bne Next1	cpx cVersion+2	beq GoodScriptNext1	cmp cVersion+4	; 1.10 ?	bne Next2	cpx cVersion+6	beq GoodScriptNext2	cmp cVersion+8	; 2.00 ?	bne NotAScript	cpx cVersion+10	bne NotAScript; If it is a compatible script file, ; find offset of ScriptName field and store to oScriptNameField;GoodScript	ldy #ScriptFlagField+2 ; past fewest ScriptFlags (2)FindNameLoop	lda Read_Buffer,y	iny	cmp #ScriptFlagEnd	; check for 2 trailing returnChars	bne FindNameLoop	iny	; point to char past returnChars (NameField)	sty oScriptNameField  ; loc of ScriptName field; then clear the cFlag and return.	clc	rts; If it is incompatible or not a script file, set the cFlag and return.NotAScript	sec	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetScriptNameLength	; (Local subroutine);;	Determines the length of the ScriptName found in the;	header of the script file (in the Read_Buffer).;; Inputs:	none;; Outputs:	A-reg contains length;; Uses:	Read_Buffer - contains script header and then some.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	sep #$0020	LongA Off	ldx #0000	; Initialize character counter	ldy oScriptNameField ; Posn of ScriptName field set by ReadScriptHeaderLengthLoop	lda Read_Buffer,y	; Get a character	cmp #Return	; Is it the end-of-name marker?	beq LengthDone	iny	; Increment index and...	inx	;   ...character counter	bra LengthLoopLengthDone	LongA On	rep #$0020	txa	; Store the length	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .CheckMsgCenter	; (External Entry Point);;	A subroutine to query the message center and get a list;	of pathnames.  If "OPEN" is requested on one or more;	pathnames, we guarantee that they are included in the;	script lists and are marked "selected" upon entry into;	the customized installation dialog.;;       Inputs:	None;;      Outputs:	cFlag: set = error,      A-reg: contains error code.;	       clear = no error, A-reg: 0000 = no OPEN message.;		            FFFF = OPEN Message;; What does it mean?  If cFlag set, error returned (probably memory error).;	  if cFlag clear & A-reg=zero, go to the automatic;	     installation dialog.;	  If cFlag clear & A-reg=minus, go to the customized;	     installation dialog and but do NOT hilite first;	     entry.;;         Uses:	<ZPTemp; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	phb	phk	plb; If messageHandle is null, there is no message.	lda messageHandle	ora messageHandle	beq MsgNoErrorExit1; Check the size of the messageHandle segment.  If it's still zero, there; is no message.	pha	pha	lda messageHandle+2	pha	lda messageHandle	pha	ldx #GetHandleSize	jsl ToolLocator	plx	ply	bne OpenRequest	cpx #0000	bne GetPointerMsgNoErrorExit1	brl MsgNoErrorExitGetPointer	lda messageHandle+2	pha	lda messageHandle	pha	jsl Dereference	pla	sta <ZPTemp	pla	sta <ZPTemp+2; The user asked us to OPEN the selected scripts.  The message format is:;   dc.l nextHandle          ; Handle of next message;   dc.w messageType         ; must be 0001 (get information);   dc.w messageData         ; 0000=open the files, 0001=print the files;   dc.b <length>'string(1)' ; 1st full pathname (Pascal string);     :      :       :;   dc.b <length>'string(n)' ; nth full pathname (Pascal string);   dc.b 00	         ; null Pascal stringOpenRequest	jsl GetListPointers	; Lists aren't locked yet	ldy #0007	; Offset to the first string -1	sty SrcY	stz StringCounter; Calculate the offset in the ScriptFileList to the beginning of the strings.	lda ScriptListSize	; Get the number of members	asl a	; X2 = X2         Multiply by entry size (6)	clc	adc ScriptListSize	; +1 = X3	asl a	; X2 = X6	sta StringBegin; We can convert each string into a GS/OS Class 1 input string because we; are always finished with the data preceeding each string as we work on; each string.StringSearchLoop	ldy StringBegin	sty DestY	ldy SrcY	; Get the index -1 to the Pascal string	lda [<ZPTemp],y	; Get length byte & preceeding byte	and #$FF00	; Clear the preceeding byte	xba	; Exchange them to form a length word	sta [<ZPTemp],y	; and store it back.*** - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - ******     NOTE:  The message center strings contain slashes (ASCII $2F)     ******            as separator characters!  Everything in the Installer      ******            deals with colons (ASCII $3A).  So, everytime we find a    ******            slash, we need to replace it with a colon.                 ******			              ******            ALSO, the comparison must be case insensitive!             ****** - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - ***	tax	; length: initialize character counter	iny	; move index past length word	iny	sep #$0020	LongA OffSlashLoop	lda [<ZPTemp],y	; Get a character from MessageCenter	cmp #'/'	; replace slashes with colons	bne @NotSlashSep	; (messages from messageCenter have slashes)	lda #SeparatorChar	sta [<ZPTemp],y	; Store colon back to the MessageCenter@NotSlashSep	iny	dex	bne SlashLoop	LongA On	rep #$0020; Go through the ScriptFileList looking for a matching string.StringCompareLoop;       First check the length words.  If they don't match, we don't need;       to check any further.	ldy SrcY	sty YSrc	lda [<ZPTemp],y	; Get lengthWord from MessageCenter	ldy DestY	sty YDest	cmp [<ScriptFilePtr],y ; Compare lengthWord from pathname list	bne NextString1;       The length words match, so start checking the strings byte by byte.	sta StringLength	; Save the length	inc ySrc	; Move past length word	inc ySrc	inc yDest	inc yDest	ldx StringLength	; Initialize character counter	sep #$0020	LongA OffStringCompareLoop1	ldy ySrc	lda [<ZPTemp],y	; Get a character from MessageCenter	jsl UpperCase8bit	; If char is lower case, convert it to upper case	sta Character	ldy yDest	; Get a character from script pathname	lda [<ScriptFilePtr],y	jsl UpperCase8bit	; If char is lower case, convert it to upper case	cmp Character	; Compare the characters	bne NextString	; Didn't match.	rep #$0020	; 16-bit memory mode for increments	inc ySrc	; Character matched.  Adjust offsets.	inc yDest	sep #$0020	; and back to 8-bit accum/mem before anyone notices	dex	; decr character counter and check for end of string.	bne StringCompareLoop1;       The strings matched!  We don't need to add this item to the list,;       but we do want to mark it as "selected"!  Update SrcY to point to;       the next messageCenter string if there is one.	LongA On	rep #$0020;               Identify the item that matched and mark it "selected".	lda StringCounter	; This contains item number -1	jsr MarkAsSelectedNextMessage	clc	ldy SrcY	lda [<ZPTemp],y	; Get the length word	adc SrcY	; Add on the previous offset	inc a	; Add one (not two) to position	sta SrcY	;  us at next string -1	tay	iny	lda [<ZPTemp],y	; Get next length byte	and #$00FF	bne @1	; If itÕs non-null, continue	lda #$FFFF	; If itÕs null, no more message strings	brl MsgNoErrorExit	;   so, indicate OPEN message found@1		;   and processed satisfactorily.	stz StringCounter	brl StringSearchLoop;       The string didn't match.  Update DestY to point to the next string;       in the ScriptFileList and reset ySrc back to the beginning of the;       current messageCenter string.NextString	LongA On	rep #$0020NextString1	clc	ldy DestY	lda [<ScriptFilePtr],y ; Get length word	adc DestY	;   Add on the previous offset	inc a	; Add two for length word	inc a	inc a	; Add one for trailing null	sta DestY	ldy SrcY	sty ySrc	inc StringCounter	lda StringCounter	; Have we checked against all strings?	cmp ScriptListSize	beq NoMatch	brl StringCompareLoop; The string from the messageCenter was not found in the ScriptFileList.; We must open the file, extract it's ScriptName and add ScriptName and its; full pathname to the respective lists.  Then check for more messagesNoMatch;       NOTE:  ReadScriptHeader requires a pointer to the full pathname as a;              GS/OS Class 1 input string in X and Y.	clc	lda <ZPTemp	adc SrcY	pha	tax	lda <ZPTemp+2	adc #0000	pha	tay;       NOTE:  AddToList requires a pointer to the full pathname as a GS/OS;              Class 1 output string in <PathBuf, a dPage location.	txa	; Simulate a GStr by backing up the	bne @1	;   pointer a couple of bytes.	dey@1	dex	bne @2	dey@2	dex	stx <PathBuf	sty <PathBuf+2	lda #$FFFF	; The GStr buffer size must "appear"	sta [<PathBuf]	;   large enough to hold the GStr.	ply	plx;       NOTE:  We must preserve our SrcY and pointer in <ZPTemp and restore;              them later.  (I know--not good programming practice!!!)	lda SrcY	; NOTE:  We must preserve our SrcY and	pha	;   pointer in <ZPTemp, which will get	pei <ZPTemp+2	;   altered below, so we can restore.	pei <ZPTemp	;   (Lousy programming--I know!!!)	jsr ReadScriptHeader	bcs NextMessage1; The script to be OPENed is indeed a legitimate and compatible script.	jsr AddToList	lda ScriptListSize	dec a	jsr MarkAsSelectedNextMessage1	pla	; Restore the stuff we saved above.	sta <ZPTemp	pla	sta <ZPTemp+2	ply	sty SrcY	brl NextMessage; Exit routines.  Don't forget to dipose of the messageCenter data memory.MsgNoErrorExit	clcMsgErrorExit	pha	php	lda MessageHandle+2	pha	lda MessageHandle	pha	ldx #DisposeHandle	jsl ToolLocator	plp	pla	plb	rtl	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .GetListPointers	; (Internal entry point);;	Dereferences the handle to both lists and placed the;	pointers in the proper dPage locations;; GetScriptFilePtr	Dereferences the handle to the ScriptFileList only.;; GetScriptListPtr	Dereferences the handle to the ScriptNameList only.;; Inputs:	none;; Outputs:	none; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .;;;	phb;;;	phk;;;	plb	jsr GetScriptFilePtr	jsr GetScriptListPtr;;;	plb	rtlGetScriptFilePtr	lda ScriptFileHdl+2	pha	lda ScriptFileHdl	pha	jsl Dereference	pla	sta <ScriptFilePtr	pla	sta <ScriptFilePtr+2	rtsGetScriptListPtr	lda ScriptListHdl+2	pha	lda ScriptListHdl	pha	jsl Dereference	pla	sta <ScriptListPtr	pla	sta <ScriptListPtr+2	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .MarkAsSelected	; (Local subroutine);;	Marks the specifiec item as selected in the ScriptList;; Inputs:	A-reg: Item number -1;; Outputs:	none;; Uses:	<ScriptListPtr - Pointer to the script list; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	clc	; Multiply by 6	asl a	;   ( X2 = X2 )	adc 1,s	;   ( +1 = X3 )	asl a	;   ( X2 = X6 )	tay	pla	iny	; We now have the index to the entry	iny	; The flags-byte is four bytes further	iny	iny	lda [<ScriptListPtr],y ; Get the flags-byte + next byte	ora #%0000000010000000 ; Mark the proper bit	sta [<ScriptListPtr],y ; And, store it back in the list	rts	Eject; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .MultiplyBy6	; (Local subroutine);; Description:	Multiplies the value in the A-reg by six and returns;	the resulting value in the A-reg;; Inputs:	A-reg contains value to be multiplied by six.;; Outputs:	A-reg contains the result of the multiplication.; . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .	pha	asl a	clc	adc 1,s	asl a	ply	rts	Eject;................................................................; OPEN call parametersOpenParms	dc.w 0002	; pCountOpen_Ref_Num	ds.w 1	; Reference numberOpen_Path	ds.l 1	; Pathname pointer; READ call parametersReadParms	dc.w 0004	; pCountRead_Ref_Num	ds.w 1	; Reference number	dc.l Read_Buffer	; Data buffer pointer	dc.l ReadBufSize	; Request count	ds.l 1	; Transfer countRead_Buffer	ds.b $800ReadBufSize	equ *-Read_Buffer; CLOSE call parametersCloseParms	dc.w 0001	; pCountClose_Ref_Num	ds.w 1	; Reference number; MiscellaneousPathLength	ds.w 1	; Length of directory's full pathnameMemorySize	ds.l 1	; Size of the script list bufferOldMemorySize	ds.l 1	; Previous size of script list bufferOldFileSize	ds.l 1	; Previous size of script filename bufferOurCounter	ds.w 1	; Loop counterScriptNameLen	ds.w 1	; Length of current	ScriptName stringDirPathLength	ds.w 1	; Length of the directory's full pathnameScriptIndex	ds.l 1NewSize	ds.l 1SrcY	ds.w 1DestY	ds.w 1ySrc	ds.w 1yDest	ds.w 1StringLength	ds.w 1StringCounter	ds.w 1StringBegin	ds.w 1Character	ds.b 1	EndP	END